ROOT=Path(__file__).parent; ASSETS=ROOT/'assets'; OUT=ROOT/'Explainable_Temporal_Plant_Growth_Forecasting_IEEE_Style_6_Pages.pdf'
W,H=A4; M=.52*inch; GAP=.18*inch; CW=(W-2*M-GAP)/2; GREEN='#155E43'; PALE='#E4F3EA'; DARK='#12372A'; BLUE='#0563C1'
for n,p in [('Times',r'C:\Windows\Fonts\times.ttf'),('TimesB',r'C:\Windows\Fonts\timesbd.ttf'),('Arial',r'C:\Windows\Fonts\arial.ttf'),('ArialB',r'C:\Windows\Fonts\arialbd.ttf')]: pdfmetrics.registerFont(TTFont(n,p))

def font(size,bold=False): return ImageFont.truetype(r'C:\Windows\Fonts\arialbd.ttf' if bold else r'C:\Windows\Fonts\arial.ttf',size)
def center(d,xy,text,f,fill=DARK):
    b=d.textbbox((0,0),text,font=f);d.text((xy[0]-(b[2]-b[0])/2,xy[1]),text,font=f,fill=fill)
def figure_workflow():
    im=PILImage.new('RGB',(1000,480),'white');d=ImageDraw.Draw(im);f=font(23,True);s=font(18);xs=[35,230,425,620,815];labs=['Soil\nrecords','Daily\nenvironment','Growth\nhistory','Adaptive\nfeatures','Forecast +\nSHAP']
    for x,label in zip(xs,labs):
        d.rounded_rectangle((x,120,x+150,275),20,fill=PALE,outline=GREEN,width=4);yy=162
        for line in label.split('\n'):center(d,(x+75,yy),line,f);yy+=30
    for x in [185,380,575,770]:d.line((x,196,x+38,196),fill=GREEN,width=5);d.polygon([(x+38,196),(x+23,187),(x+23,205)],fill=GREEN)
    center(d,(500,335),'Timestamp-aware integration  •  leakage-safe features  •  artifact-gated inference',s,'#305A47')
    im.save(ASSETS/'ieee_workflow.png')
def figure_architecture():
    im=PILImage.new('RGB',(1000,500),'white');d=ImageDraw.Draw(im);f=font(22,True);s=font(17);boxes=[(50,'React\nclient'),(280,'Spring Boot\nAPI'),(510,'MySQL'),(740,'FastAPI\nML service')]
    for x,l in boxes:
        d.rounded_rectangle((x,95,x+180,220),18,fill=PALE,outline=GREEN,width=4);yy=132
        for line in l.split('\n'):center(d,(x+90,yy),line,f);yy+=30
    for x in [230,460,690]:d.line((x,157,x+40,157),fill=GREEN,width=5);d.polygon([(x+40,157),(x+25,148),(x+25,166)],fill=GREEN)
    d.rounded_rectangle((715,335,920,440),18,fill='#D2EAD9',outline=GREEN,width=4);center(d,(817,365),'Versioned model',f);center(d,(817,395),'artifacts',f)
    d.line((830,220,830,335),fill=GREEN,width=4);d.polygon([(830,335),(820,320),(840,320)],fill=GREEN)
    center(d,(500,275),'Backend authorizes access and persists inputs, outputs, metadata and explanations.',s,'#305A47')
    im.save(ASSETS/'ieee_architecture.png')
def figure_dashboard():
    im=PILImage.new('RGB',(1000,600),'white');d=ImageDraw.Draw(im);b=font(23,True);s=font(17);tiny=font(14)
    d.rounded_rectangle((25,25,975,575),20,fill='#F7FAF8',outline='#55A97A',width=5);d.rectangle((25,25,220,575),fill='#174F3A');d.text((52,58),'Verdant Forecast',font=b,fill='white')
    for i,x in enumerate(['Dashboard','Plants','Data imports','Forecasts','Model evaluation']):d.text((55,125+i*48),x,font=s,fill='white' if i==0 else '#D8F1E2')
    d.text((260,65),'Research dashboard',font=b,fill=DARK);d.text((260,102),'Measured observations, forecast status and traceable model outputs',font=tiny,fill='#4C6358')
    for x,title,value in [(260,'Plants','Not available'),(480,'Latest height','Not available'),(700,'Model status','Awaiting artifact')]:
        d.rounded_rectangle((x,145,x+185,230),13,fill='white',outline='#C7D9CE',width=2);d.text((x+15,163),title,font=tiny,fill='#4C6358');d.text((x+15,192),value,font=s,fill=DARK)
    d.rounded_rectangle((260,260,930,470),14,fill='white',outline='#C7D9CE',width=2);d.text((285,282),'Height history and forecast',font=s,fill=DARK);d.line((300,425,900,425),fill='#C4D3CA',width=2);d.line((300,320,300,425),fill='#C4D3CA',width=2)
    d.text((390,365),'No compatible trained forecast available',font=s,fill='#65766D');d.text((390,392),'Import repeated timestamped height measurements to train and evaluate.',font=tiny,fill='#65766D')
    d.rounded_rectangle((260,495,930,545),12,fill='#EAF5EE',outline='#A9D6B8',width=1);d.text((280,512),'Prediction output is labelled as an estimate, not a measurement.',font=tiny,fill='#285A41')
    im.save(ASSETS/'ieee_dashboard.png')
def figure_shap():
    im=PILImage.new('RGB',(1000,500),'white');d=ImageDraw.Draw(im);b=font(26,True);s=font(18);d.text((45,30),'SHAP Explanation Output',font=b,fill=DARK);d.text((45,72),'Generated only after a fitted artifact returns a forecast',font=s,fill='#527064')
    labels=[('Previous height','Model contribution'),('Temperature trend','Model contribution'),('Soil moisture','Model contribution'),('Humidity trend','Model contribution')]; ys=[145,220,295,370]
    for (name,_),y in zip(labels,ys):
        d.text((55,y),name,font=s,fill=DARK);d.rounded_rectangle((300,y,800,y+26),10,fill='#E4ECE7');d.rounded_rectangle((300,y,300+[390,280,210,165][ys.index(y)],y+26),10,fill='#2A9869');d.text((825,y+2),'stored with prediction',font=font(15),fill='#305A47')
    im.save(ASSETS/'ieee_shap.png')
def figure_evaluation():
    im=PILImage.new('RGB',(1000,500),'white');d=ImageDraw.Draw(im);b=font(25,True);s=font(17);d.text((42,28),'Model Evaluation Reporting Panel',font=b,fill=DARK);d.text((42,66),'Bars are intentionally withheld until held-out plant-height evaluation is complete',font=s,fill='#527064')
    d.line((125,420,920,420),fill='#65766D',width=3);d.line((125,120,125,420),fill='#65766D',width=3)
    models=['Persistence','RF','XGBoost','GRU','LSTM','Fusion'];xs=[175,300,425,550,675,800]
    for x,m in zip(xs,models):d.rectangle((x,280,x+60,420),fill='#CFD9D4',outline='#8CA097');center(d,(x+30,435),m,font(14),DARK);center(d,(x+30,345),'Pending',font(14),'#52665C')
    d.text((140,105),'Real MAE, RMSE and R squared values appear here only after chronological testing.',font=s,fill='#305A47')
    im.save(ASSETS/'ieee_evaluation.png')

S={
'h':ParagraphStyle('h',fontName='TimesB',fontSize=10,leading=11.5,alignment=TA_CENTER,spaceAfter=4,spaceBefore=2),
'sub':ParagraphStyle('sub',fontName='TimesB',fontSize=9,leading=10.5,spaceAfter=2,spaceBefore=3),
'body':ParagraphStyle('body',fontName='Times',fontSize=8.9,leading=10.2,alignment=TA_JUSTIFY,spaceAfter=4),
'cap':ParagraphStyle('cap',fontName='Times',fontSize=7.5,leading=8.6,alignment=TA_CENTER,spaceBefore=2,spaceAfter=4),
'cell':ParagraphStyle('cell',fontName='Times',fontSize=7.1,leading=8.2,alignment=TA_LEFT),
'cellh':ParagraphStyle('cellh',fontName='TimesB',fontSize=7.1,leading=8.2,alignment=TA_CENTER,textColor=colors.white),
'ref':ParagraphStyle('ref',fontName='Times',fontSize=8.2,leading=9.5,alignment=TA_LEFT,spaceAfter=3),
}
def P(x,style='body'):return Paragraph(x,S[style])
def T(rows,widths):
    data=[]
    for ri,row in enumerate(rows):data.append([Paragraph(str(x),S['cellh'] if ri==0 else S['cell']) for x in row])
    t=Table(data,colWidths=widths,hAlign='LEFT',repeatRows=1)
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),HexColor(GREEN)),('GRID',(0,0),(-1,-1),.35,HexColor('#BFCBC4')),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),3),('RIGHTPADDING',(0,0),(-1,-1),3),('TOPPADDING',(0,0),(-1,-1),3),('BOTTOMPADDING',(0,0),(-1,-1),3)]));return t
def fig(name,cap):return [Image(str(ASSETS/name),width=CW,height=CW*.48),P(cap,'cap')]
def footer(c,doc):
    c.saveState();c.setFont('Times',8);c.drawCentredString(W/2,.3*inch,str(doc.page));c.restoreState()
def first_header(c,doc):
    footer(c,doc)
    x=M; top=H-.45*inch
    title=Paragraph('An Explainable Adaptive Temporal Learning Framework for Early Plant Growth Forecasting Using Integrated Soil Environmental and Historical Growth Data',ParagraphStyle('tt',fontName='TimesB',fontSize=18,leading=20.5,alignment=TA_CENTER))
    _,hh=title.wrap(W-2*M,100);title.drawOn(c,x,top-hh)
    author_text=[('Ms. B. Rajani','Project Guide | Assistant Professor<br/>Department of Artificial Intelligence and Machine Learning<br/>Mohan Babu University, Tirupati, Andhra Pradesh, India',''),('Golla Kalpana Devi','Department of Computer Science and Engineering (AIML)<br/>Mohan Babu University, Tirupati, Andhra Pradesh, India','gollakalpanadevi@gmail.com'),('Tammineni Jagadeesh','Department of Computer Science and Engineering (AIML)<br/>Mohan Babu University, Tirupati, Andhra Pradesh, India','Jagadeesht805@gmail.com'),('Penumuru Partha','Department of Computer Science and Engineering (AIML)<br/>Mohan Babu University, Tirupati, Andhra Pradesh, India',''),('Pathipati Hitesh Naidu','Department of Computer Science and Engineering (AIML)<br/>Mohan Babu University, Tirupati, Andhra Pradesh, India','hiteshpathipati45@gmail.com'),('Devarala Vamsi Krishna','Department of Computer Science and Engineering (AIML)<br/>Mohan Babu University, Tirupati, Andhra Pradesh, India','')]
    cells=[]
    for n,a,e in author_text:
        cells.append(Paragraph(f'<b>{n}</b><br/>{a}'+(f'<br/><font color="{BLUE}">{e}</font>' if e else ''),ParagraphStyle('au',fontName='Times',fontSize=6.6,leading=7.7,alignment=TA_CENTER)))
    tab=Table([cells[:3],cells[3:]],colWidths=[(W-2*M)/3]*3,style=[('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),2),('RIGHTPADDING',(0,0),(-1,-1),2),('TOPPADDING',(0,0),(-1,-1),1),('BOTTOMPADDING',(0,0),(-1,-1),3)])
    tw,th=tab.wrap(W-2*M,90);tab.drawOn(c,x,top-hh-th-9)
    abs_y=top-hh-th-18
    abst=Paragraph('<b>Abstract—</b> Plant growth reflects interacting soil, environmental, and historical conditions. This paper presents an explainable adaptive temporal learning framework that forecasts future plant height using soil records, daily environment observations, and plant-specific growth history. It combines leakage-safe temporal features with persistence, linear, Random Forest, XGBoost, GRU, LSTM, and validation-trained fusion models. SHAP links explanations to the exact fitted artifact and input. Evaluation uses chronological splits and regression metrics. The project is implemented through React, Spring Boot, MySQL, and FastAPI. Since the supplied dataset has no repeated height target, the paper reports a reproducible design and does not fabricate performance claims.',ParagraphStyle('ab',fontName='Times',fontSize=8.8,leading=10.1,alignment=TA_JUSTIFY))
    _,ah=abst.wrap(W-2*M,100);abst.drawOn(c,x,abs_y-ah)
    key=Paragraph('<b>Index Terms—</b> Plant growth forecasting, temporal learning, explainable AI, SHAP, feature selection, precision agriculture.',ParagraphStyle('k',fontName='Times',fontSize=8.3,leading=9.5,alignment=TA_JUSTIFY))
    _,kh=key.wrap(W-2*M,50);key.drawOn(c,x,abs_y-ah-kh-4)

def build():
    for f in [figure_workflow,figure_architecture,figure_dashboard,figure_shap,figure_evaluation]:f()
    # Reserve a generous first-page masthead area for the title, authors,
    # abstract and index terms before the two-column body begins.
    top_first=H-4.05*inch
    f1=[Frame(M,.45*inch,CW,top_first-.45*inch,showBoundary=0,id='f1a',leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0),Frame(M+CW+GAP,.45*inch,CW,top_first-.45*inch,showBoundary=0,id='f1b',leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0)]
    f2=[Frame(M,.45*inch,CW,H-.95*inch,showBoundary=0,id='f2a',leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0),Frame(M+CW+GAP,.45*inch,CW,H-.95*inch,showBoundary=0,id='f2b',leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0)]
    doc=BaseDocTemplate(str(OUT),pagesize=A4,leftMargin=M,rightMargin=M,topMargin=.45*inch,bottomMargin=.45*inch,pageTemplates=[PageTemplate(id='first',frames=f1,onPage=first_header),PageTemplate(id='later',frames=f2,onPage=footer)])
    st=[NextPageTemplate('later')]
    # Page 1 lower two columns
    st += [P('I. INTRODUCTION','h'),P('Plant growth monitoring supports data-driven cultivation, but current conditions alone do not represent the accumulated effects of prior growth, weather and soil. The proposed system forecasts a future plant-height value in centimetres at a declared horizon. Every completed prediction retains the origin timestamp, model version, feature pipeline version and input snapshot required for audit.','body'),P('Conventional tabular learning represents nonlinear interactions but can treat observations independently. Plant development is temporal: earlier height and environmental exposure influence later growth. The framework therefore uses timestamp-aware joins, per-plant history, lagged values, rolling statistics and an explicit horizon definition. It is a research decision-support system; it does not diagnose disease, guarantee yield or treat SHAP attribution as causation.','body'),P('A. Contributions','sub'),P('The contribution is a full-stack framework that integrates three modalities, compares tabular and temporal learners, performs adaptive feature selection using training data only, combines compatible branches through validation-trained fusion, and gives artifact-linked SHAP explanations.','body'),FrameBreak(),P('II. RELATED WORK AND BASE PAPER CONTEXT','h'),P('Recent work on greenhouse growth modelling demonstrates the value of environmental sensing, recurrent models and multimodal learning for plant-development trajectories. LSTM-based tomato-height studies show that historical conditions improve prediction relative to instantaneous inputs. Explainable AI is increasingly used to inspect feature contributions in agricultural models.','body'),P('The selected base paper by Condò et al. introduces a self-adhesive fiber Bragg grating wearable that physically monitors stem elongation. It is a measurement system based on optical strain sensing. The present project is different: it forecasts a later numerical height from prior soil, environmental and growth records. The approaches can be complementary, but the proposed software does not reproduce or replace the sensor’s physical measurement.','body'),P('B. Research Gap','sub'),P('A practical gap remains for an auditable application that unifies soil provenance, daily environment records, repeated plant-height observations, temporal feature construction, adaptive selection, fusion and explanation under a chronological evaluation protocol.','body'),PageBreak()]
    # Page 2
    st += [P('III. PROPOSED FORECASTING FRAMEWORK','h'),*fig('ieee_workflow.png','Fig. 1. Integrated plant-growth forecasting workflow.'),P('At a forecast origin, records are aligned using plant identifier, location and real timestamps. Soil records are reused only when their temporal interpretation supports it. Missing values remain unknown; no missing height, moisture or weather value is invented. The feature pipeline uses only information available by the origin time.','body'),P('A. Input Modalities','sub'),T([['Modality','Examples'],['Soil','pH, moisture, nitrogen, phosphorus, potassium, texture'],['Environment','Temperature, humidity, precipitation, solar radiation'],['Growth','Plant ID, measurement timestamp, height, stage']], [1.02*inch,2.26*inch]),P('Table I. Input modalities.','cap'),FrameBreak(),P('B. Base Paper and Project Comparison','sub'),T([['Aspect','Base paper','This project'],['Goal','Measure elongation','Forecast future height'],['Input','FBG strain response','Soil, environment, history'],['Output','Physical measurement','Prediction + SHAP'],['Evaluation','Sensor metrology','Chronological MAE, RMSE, R squared']], [.62*inch,1.33*inch,1.33*inch]),P('Table II. Base-paper distinction.','cap'),P('C. Target and Horizon','sub'),P('The primary research target is future plant height. A valid label is the real plant-height observation nearest to origin plus the configured horizon within a documented tolerance. Origins without a valid later measurement are excluded. Growth amount may be treated only as a separate labelled experiment, not mixed with the height target.','body'),P('D. Temporal Feature Engineering','sub'),P('Examples include previous height, observed growth rate, lagged soil moisture where measured, rolling temperature and humidity summaries, cumulative precipitation, observation gaps and planting-age features. The pipeline prevents future observations from entering historical feature vectors.','body'),PageBreak()]
    # p3
    st += [P('IV. LEARNING MODELS AND FUSION','h'),P('The persistence baseline predicts the latest measured height. Linear regression is included as a simple benchmark. Random Forest and XGBoost consume selected tabular features. GRU and LSTM consume ordered per-plant sequences. All comparable models use the same target definition and chronological partitions.','body'),T([['Model','Role'],['Persistence','Minimum future-height baseline'],['Linear regression','Linear tabular benchmark'],['Random Forest','Nonlinear tabular benchmark'],['XGBoost','Boosted tabular benchmark'],['GRU / LSTM','Temporal sequence benchmarks'],['Stacked fusion','Validation-trained integration']], [1.3*inch,1.98*inch]),P('Table III. Model family.','cap'),P('A. Adaptive Feature Selection','sub'),P('Importance- or permutation-based selection is fitted on training observations only. The selected feature list, order, scaler and imputation settings are stored with the model artifact. Validation data may select a feature-selection configuration, but the held-out test set is never used to choose features.','body'),FrameBreak(),P('B. Fusion Strategy','sub'),P('The primary fusion strategy is stacking. Base predictors are trained on the training period and generate temporally valid predictions. A meta-regressor is trained using those base outputs and selected context where justified. The configuration is selected on validation data, frozen, and then assessed once on the final test period.','body'),P('C. SHAP Explainability','sub'),*fig('ieee_shap.png','Fig. 2. Proposed SHAP output structure. Contributions are populated only for a fitted model and exact input.'),P('Tree explainers are used for tree models. Neural explanations require a validated explainer and representative background data. For stacked fusion, the final explanation must identify meta-model behaviour; base-model values alone must not be misrepresented as a complete fusion explanation.','body'),PageBreak()]
    # p4
    st += [P('V. FULL STACK IMPLEMENTATION','h'),*fig('ieee_architecture.png','Fig. 3. React to Spring Boot to MySQL and FastAPI architecture.'),P('React provides the user interface. Spring Boot authenticates users using JWT, enforces ownership, validates requests, stores observations and persists prediction metadata. MySQL retains plants, locations, soil/environmental/growth records, imports, predictions and evaluations. FastAPI owns preprocessing, artifact loading, forecasting, training and explainability.','body'),P('A. Secure Prediction Workflow','sub'),P('The browser never calls the ML service directly. The backend retrieves only authorized records, builds a validated ML request, handles unavailable artifacts and timeouts, and saves the returned prediction with its model version and input snapshot.','body'),FrameBreak(),P('B. Dashboard Output Design','sub'),*fig('ieee_dashboard.png','Fig. 4. Original project dashboard concept. It intentionally displays unavailable values until valid records and trained artifacts exist.'),P('Measured values and forecasts are visually distinct. The result view labels output as “prediction, not measurement”, displays data-quality warnings, and later displays the measured future height and absolute error when it is recorded.','body'),P('C. Data Quality','sub'),P('The system rejects invalid pH, impossible humidity, negative height, duplicate growth timestamps, unsupported horizons, unknown plants and insufficient history. It never silently changes missing values to zero. Import audit records preserve file name, row counts, rejection causes and validation warnings.','body'),PageBreak()]
    #p5
    st += [P('VI. EVALUATION AND RESULTS REPORTING','h'),P('Forecasting experiments require chronological partitions rather than random mixing. The earliest period fits preprocessing and models; the following period selects hyperparameters and fusion; the newest period is untouched until final assessment. The paper must report date ranges, sample count and target/horizon alongside each metric.','body'),*fig('ieee_evaluation.png','Fig. 5. Performance-reporting layout. Actual model bars are withheld until valid chronological evaluation is run.'),P('A. Metrics','sub'),T([['Metric','Meaning'],['MAE','Average absolute future-height error in cm'],['RMSE','Penalizes larger height errors'],['R squared','Explained variation; guarded for small/constant sets']], [1.05*inch,2.23*inch]),P('Table IV. Regression metrics.','cap'),P('B. Current Dataset Observation','sub'),P('The supplied aggregate greenhouse file contains environmental and aggregate fruit/biomass fields but marks plant_height_cm as not provided. It cannot train or validate a plant-height forecaster. That constraint is recorded instead of hidden.','body'),FrameBreak(),P('C. Results Status','sub'),T([['Model','7-day result'],['Persistence','Not evaluated: height data required'],['Random Forest','Not evaluated: height data required'],['XGBoost','Not evaluated: height data required'],['GRU / LSTM','Not evaluated: sequences required'],['Fusion','Not evaluated: valid base artifacts required']], [1.15*inch,2.13*inch]),P('Table V. Current evaluation status.','cap'),P('No numerical accuracy, MAE, RMSE, R squared, SHAP ranking, or “best model” claim is inserted before an experiment produces those results. This protects the integrity of the conference submission. Once repeated timestamped height measurements are available, the training pipeline produces the metrics table and real chart from persisted evaluation outputs.','body'),P('VII. CONCLUSION AND FUTURE WORK','h'),P('The proposed framework brings together authenticated observation management, leakage-safe temporal learning, adaptive selection, fusion, SHAP and chronological validation for early plant-growth forecasting. The next research step is collection or licensing of repeated per-plant height data at a frequency sufficient for the selected horizon. Future work includes uncertainty estimates, cross-location validation, species transfer and integration of real sensor measurements as additional inputs.','body'),PageBreak()]
    # p6
    st += [P('VIII. APPLICATION WORKFLOW','h'),T([['Step','Outcome'],['Register plant and location','Stable plant and location identifiers'],['Store observations','Source, timestamp and quality status'],['Request forecast','Validated artifact-gated inference'],['Save prediction','Input snapshot, version and SHAP output'],['Record actual measurement','Absolute error and evaluation history']], [1.12*inch,2.16*inch]),P('Table VI. End-to-end workflow.','cap'),P('A. Reproducibility Checklist','sub'),T([['Requirement','Implementation'],['Target','Future plant height in cm; declared horizon/tolerance'],['Split','Chronological train, validation and held-out test'],['Transforms','Fit on training period only'],['Artifacts','Store feature order, pipeline/model versions and configuration'],['Interpretation','SHAP linked to exact model and input; no causal claim']], [1.05*inch,2.23*inch]),P('Table VII. Minimum reproducibility controls.','cap'),FrameBreak(),P('REFERENCES','h')]
    refs=['[1] I. Condò et al., “An Innovative Self-Adhesive Wearable Sensor Based on Fiber Bragg Grating Technology for Plant Growth Monitoring,” <i>IEEE Sensors Journal</i>, vol. 25, no. 2, pp. 2705-2713, 2025.','[2] L. Cha et al., “Artificial intelligence based prediction of tomato plant height using environmental determinants,” <i>Computers and Electronics in Agriculture</i>, 2022.','[3] M. Riesselman et al., “Self-supervised learning of plant growth trajectories from multimodal greenhouse data,” 2024.','[4] S. M. Lundberg and S.-I. Lee, “A unified approach to interpreting model predictions,” <i>NeurIPS</i>, 2017.','[5] L. Breiman, “Random Forests,” <i>Machine Learning</i>, vol. 45, pp. 5-32, 2001.','[6] T. Chen and C. Guestrin, “XGBoost: A Scalable Tree Boosting System,” <i>ACM SIGKDD</i>, 2016.','[7] K. Cho et al., “Learning Phrase Representations using RNN Encoder-Decoder,” <i>EMNLP</i>, 2014.','[8] S. Hochreiter and J. Schmidhuber, “Long Short-Term Memory,” <i>Neural Computation</i>, 1997.','[9] ISRIC, “SoilGrids,” https://soilgrids.org/.','[10] NASA POWER, “Daily API,” https://power.larc.nasa.gov/docs/services/api/temporal/daily/.']
    st += [P(x,'ref') for x in refs]
    doc.build(st)
if __name__=='__main__': build()
